<?php
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../database/conexao.php';exigirLogin();validarCsrf();if(usuarioLogadoTipo()==='mei'){header('Location: ../pages/dashboard.php');exit;}
$pdo=conectar();$uid=usuarioLogadoId();$acao=$_POST['acao']??'';
function nmeta($v):float{return max(0,(float)str_replace(',','.',(string)$v));}
if($acao==='criar'){$titulo=trim($_POST['titulo']??'');$meta=nmeta($_POST['valor_meta']??0);$atual=nmeta($_POST['valor_atual']??0);$prazo=!empty($_POST['prazo'])?$_POST['prazo']:null;if($titulo!==''&&$meta>0){$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO metas (usuario_id,titulo,valor_meta,valor_atual,prazo,concluida) VALUES (:uid,:titulo,:meta,:atual,:prazo,:c)');$s->execute(['uid'=>$uid,'titulo'=>$titulo,'meta'=>$meta,'atual'=>$atual,'prazo'=>$prazo,'c'=>$atual>=$meta?1:0]);$id=(int)$pdo->lastInsertId();if($atual>0){$m=$pdo->prepare('INSERT INTO meta_movimentacoes (meta_id,usuario_id,tipo,valor,observacao,data_movimentacao) VALUES (:mid,:uid,"aporte",:valor,"Valor inicial",:data)');$m->execute(['mid'=>$id,'uid'=>$uid,'valor'=>$atual,'data'=>date('Y-m-d')]);}$pdo->commit();}}
if(in_array($acao,['aporte','retirada'],true)){$id=(int)($_POST['id']??0);$valor=nmeta($_POST['valor']??0);$obs=trim($_POST['observacao']??'');$data=$_POST['data_movimentacao']??date('Y-m-d');$s=$pdo->prepare('SELECT valor_meta,valor_atual FROM metas WHERE id=:id AND usuario_id=:uid');$s->execute(['id'=>$id,'uid'=>$uid]);$meta=$s->fetch();if($meta&&$valor>0){$novo=$acao==='aporte'?(float)$meta['valor_atual']+$valor:max(0,(float)$meta['valor_atual']-$valor);$pdo->beginTransaction();$pdo->prepare('UPDATE metas SET valor_atual=:v,concluida=:c WHERE id=:id AND usuario_id=:uid')->execute(['v'=>$novo,'c'=>$novo>=(float)$meta['valor_meta']?1:0,'id'=>$id,'uid'=>$uid]);$pdo->prepare('INSERT INTO meta_movimentacoes (meta_id,usuario_id,tipo,valor,observacao,data_movimentacao) VALUES (:mid,:uid,:tipo,:valor,:obs,:data)')->execute(['mid'=>$id,'uid'=>$uid,'tipo'=>$acao,'valor'=>$valor,'obs'=>$obs?:null,'data'=>$data]);$pdo->commit();}}
if($acao==='excluir'){$pdo->prepare('DELETE FROM metas WHERE id=:id AND usuario_id=:uid')->execute(['id'=>(int)($_POST['id']??0),'uid'=>$uid]);}
$ret=(int)($_POST['id']??0);header('Location: ../pages/metas.php'.($ret?'?meta='.$ret:''));exit;
